compile.workshop:
variables {
    global:
        0: nested
}

rule ("nested indexed assignments") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable At Index(nested, 0, Append To Array(Append To Array(Array Slice(First Of(Global.nested), 0, 1), Array(2)), Array Slice(First Of(Global.nested), Add(1, 1), 999999999999)));
        Set Global Variable At Index(nested, 1, Append To Array(Append To Array(Array Slice(Value In Array(Global.nested, 1), 0, 0), Array(Add(First Of(Value In Array(Global.nested, 1)), 3))), Array Slice(Value In Array(Global.nested, 1), Add(0, 1), 999999999999)));
        Set Global Variable At Index(nested, 0, Append To Array(Append To Array(Array Slice(First Of(Global.nested), 0, 1), Array(Append To Array(Append To Array(Array Slice(Value In Array(First Of(Global.nested), 1), 0, 2), Array(4)), Array Slice(Value In Array(First Of(Global.nested), 1), Add(2, 1), 999999999999)))), Array Slice(First Of(Global.nested), Add(1, 1), 999999999999)));
    }
}

